import Link from "next/link";
import { notFound } from "next/navigation";

import {
  getListing,
  getListings,
} from "@/lib/api";

interface ListingPageProps {
  params: Promise<{
    id: string;
  }>;
}

export default async function ListingPage({
  params,
}: ListingPageProps) {

  const { id } = await params;

  const listingId = Number(id);

  if (!Number.isFinite(listingId)) {
    notFound();
  }


  let listing;

  try {
    listing = await getListing(listingId);
  } catch {
    notFound();
  }


  const allListings = await getListings();


  /* =========================================
     SIMILAR LISTINGS
  ========================================= */

  const similarListings =
    allListings
      .filter(
        (item) => item.id !== listing.id
      )
      .sort((a, b) => {

        const aSameType =
          a.property_type ===
          listing.property_type;

        const bSameType =
          b.property_type ===
          listing.property_type;

        if (aSameType && !bSameType) {
          return -1;
        }

        if (!aSameType && bSameType) {
          return 1;
        }

        return 0;
      })
      .slice(0, 4);


  const images = listing.images
    .slice(0, 5);


  const mapUrl =
    listing.latitude !== null &&
    listing.longitude !== null
      ? `https://www.openstreetmap.org/export/embed.html?bbox=${
          listing.longitude - 0.05
        }%2C${
          listing.latitude - 0.04
        }%2C${
          listing.longitude + 0.05
        }%2C${
          listing.latitude + 0.04
        }&layer=mapnik&marker=${
          listing.latitude
        }%2C${listing.longitude}`
      : null;


  return (
    <main className="listing-detail-page">

      {/* =====================================
          TOP BAR
      ===================================== */}

      <header className="detail-header">

        <Link
          href="/"
          className="back-button"
        >
          ←
        </Link>

        <Link
          href="/"
          className="detail-logo"
        >
          <span className="detail-logo-icon">
            ♧
          </span>

          <span>
            airbnb
          </span>
        </Link>

        <div className="detail-header-actions">

          <button>
            Share
          </button>

          <button>
            ♡ Save
          </button>

        </div>

      </header>


      {/* =====================================
          CONTENT
      ===================================== */}

      <div className="detail-container">


        {/* TITLE */}

        <div className="detail-title-section">

          <h1>
            {listing.title}
          </h1>

          <div className="detail-meta">

            <span>
              ★ {listing.rating.toFixed(2)}
            </span>

            <span>·</span>

            <span>
              {listing.review_count} reviews
            </span>

            <span>·</span>

            <span>
              {listing.location}
            </span>

          </div>

        </div>


        {/* =================================
            IMAGE GALLERY
        ================================= */}

        <div
          className={`detail-gallery ${
            images.length === 1
              ? "gallery-one"
              : ""
          }`}
        >

          {images.map((image, index) => (

            <div
              key={image.id}
              className={`gallery-image gallery-image-${index}`}
            >

              <img
                src={image.image_url}
                alt={`${listing.title} ${
                  index + 1
                }`}
              />

            </div>

          ))}

        </div>


        {/* =================================
            MAIN AREA
        ================================= */}

        <div className="detail-main">


          {/* LEFT */}

          <div className="detail-left">

            <section className="host-section">

              <div>

                <h2>
                  {listing.property_type} hosted
                  by {listing.host.name}
                </h2>

                <p>
                  Guests · Entire place ·
                  {listing.location}
                </p>

              </div>


              <div className="host-avatar">

                {listing.host.name
                  .charAt(0)
                  .toUpperCase()}

              </div>

            </section>


            <div className="detail-divider" />


            {/* DESCRIPTION */}

            <section className="detail-section">

              <h2>
                About this place
              </h2>

              <p className="description">
                {listing.description}
              </p>

            </section>


            <div className="detail-divider" />


            {/* AMENITIES */}

            <section className="detail-section">

              <h2>
                What this place offers
              </h2>


              <div className="amenities-grid">

                {listing.amenities.map(
                  (item) => (

                    <div
                      key={item.id}
                      className="amenity-item"
                    >

                      <span>
                        ✓
                      </span>

                      <span>
                        {item.amenity.name}
                      </span>

                    </div>

                  )
                )}

              </div>

            </section>


            <div className="detail-divider" />


            {/* =================================
                MAP
            ================================= */}

            <section className="detail-section">

              <h2>
                Where you'll be
              </h2>

              <p className="map-location">
                {listing.location}
              </p>


              <div className="listing-map">

                {mapUrl ? (
                  <iframe
                    src={mapUrl}
                    title={`Map of ${listing.location}`}
                    loading="lazy"
                  />
                ) : (
                  <div className="map-fallback">
                    <span>📍</span>
                    <strong>
                      {listing.location}
                    </strong>
                  </div>
                )}

              </div>

            </section>

          </div>


          {/* =================================
              RESERVATION CARD
          ================================= */}

          <aside className="reservation-wrapper">

            <div className="reservation-card">

              <div className="reservation-price">

                <strong>
                  ₹
                  {listing.price_per_night.toLocaleString(
                    "en-IN"
                  )}
                </strong>

                <span>
                  night
                </span>

              </div>


              <div className="reservation-fields">

                <div className="reservation-field">

                  <strong>
                    CHECK-IN
                  </strong>

                  <span>
                    Add date
                  </span>

                </div>

                <div className="reservation-field">

                  <strong>
                    CHECKOUT
                  </strong>

                  <span>
                    Add date
                  </span>

                </div>

              </div>


              <button className="guest-field">

                <span>

                  <strong>
                    GUESTS
                  </strong>

                  <small>
                    1 guest
                  </small>

                </span>

                <span>
                 ⌄
                </span>

              </button>


              <button className="reserve-button">
                Reserve
              </button>


              <p className="reserve-note">
                You won't be charged yet
              </p>


              <div className="price-row">

                <span>
                  ₹
                  {listing.price_per_night.toLocaleString(
                    "en-IN"
                  )} × 1 night
                </span>

                <span>
                  ₹
                  {listing.price_per_night.toLocaleString(
                    "en-IN"
                  )}
                </span>

              </div>


              <div className="price-row">

                <span>
                  Cleaning fee
                </span>

                <span>
                  ₹500
                </span>

              </div>


              <div className="price-row">

                <span>
                  Service fee
                </span>

                <span>
                  ₹
                  {Math.round(
                    listing.price_per_night *
                      0.12
                  ).toLocaleString("en-IN")}
                </span>

              </div>


              <div className="reservation-total">

                <strong>
                  Total
                </strong>

                <strong>
                  ₹
                  {Math.round(
                    listing.price_per_night +
                      500 +
                      listing.price_per_night *
                        0.12
                  ).toLocaleString("en-IN")}
                </strong>

              </div>

            </div>

          </aside>

        </div>


        {/* =====================================
            SIMILAR HOMES
        ===================================== */}

        {similarListings.length > 0 && (

          <section className="similar-section">

            <h2>
              Similar homes you may like
            </h2>

            <div className="similar-grid">

              {similarListings.map(
                (item) => (

                  <Link
                    key={item.id}
                    href={`/listings/${item.id}`}
                    className="similar-card"
                  >

                    <div className="similar-image">

                      <img
                        src={
                          item.images?.[0]
                            ?.image_url
                        }
                        alt={item.title}
                      />

                      <span className="similar-heart">
                        ♡
                      </span>

                    </div>


                    <div className="similar-info">

                      <div className="similar-title">

                        <strong>
                          {item.location}
                        </strong>

                        <span>
                          ★{" "}
                          {item.rating.toFixed(
                            2
                          )}
                        </span>

                      </div>

                      <p>
                        {item.title}
                      </p>

                      <strong>
                        ₹
                        {item.price_per_night.toLocaleString(
                          "en-IN"
                        )}{" "}
                        night
                      </strong>

                    </div>

                  </Link>

                )
              )}

            </div>

          </section>

        )}

      </div>

    </main>
  );
}